import { v5 as uuidv5 } from 'uuid';
const STARTER_NAMESPACE = 'ff4bd5b6-37c8-4d72-a6c5-842e794cc53d';
export const getTeamspaceStarterNodeIds = (deploymentId) => {
    const fileId = (key) => uuidv5(`${deploymentId}:teamspace:${key}`, STARTER_NAMESPACE);
    return {
        folderId: `private-folder-${fileId('welcome-folder')}`,
        guideId: `private-page-${fileId('teamspace')}`,
    };
};
export const getPersonalStarterNodeIds = (deploymentId, userId) => ['welcome', 'personal'].map((key) => `private-page-${uuidv5(`${deploymentId}:${userId}:${key}`, STARTER_NAMESPACE)}`);
